import React, { useState, ReactNode, useRef } from 'react';

import './legacy-expansion-panel.styles.scss';

interface LegacyExpansionPanelProps {
  /** Panel header/title */
  header: string;
  /** Content to show when expanded */
  children: ReactNode;
  /** Whether the panel is open by default */
  defaultExpanded?: boolean;
  /** Whether the panel is disabled (not clickable) */
  disabled?: boolean;
  /** Optional callback when toggled: (isOpen) => void */
  // eslint-disable-next-line no-unused-vars
  onToggle?: (isOpen: boolean) => void;
}

const LegacyExpansionPanel: React.FC<LegacyExpansionPanelProps> = ({
  header,
  children,
  defaultExpanded = false,
  disabled = false,
  onToggle,
}) => {
  const [isOpen, setIsOpen] = useState<boolean>(defaultExpanded);
  const contentRef = useRef<HTMLDivElement>(null);

  const togglePanel = () => {
    if (disabled) {
      return;
    }
    setIsOpen((prev) => {
      const next = !prev;
      onToggle?.(next);
      return next;
    });
  };

  return (
    <div className={`legacy-expansion-panel ${disabled ? 'disabled' : ''}`}>
      <button
        type="button"
        className="expansion-panel__header"
        onClick={togglePanel}
        aria-expanded={isOpen}
        aria-disabled={disabled}
        // aria-controls references the ID of the content region
        aria-controls="expansion-panel-content"
        disabled={disabled}
      >
        <span className="expansion-panel__header-text">{header}</span>
        <span
          className={`expansion-panel__icon ${
            isOpen ? 'expanded' : 'collapsed'
          }`}
          aria-hidden="true"
        >
          {isOpen ? '▾' : '▸'}
        </span>
      </button>

      <div
        id="expansion-panel-content"
        className={`expansion-panel__content ${isOpen ? 'open' : ''}`}
        ref={contentRef}
        role="region"
        aria-labelledby="expansion-panel-header"
        style={{
          maxHeight: isOpen
            ? `${contentRef.current?.scrollHeight ?? 0}px`
            : '0px',
        }}
      >
        <div className="expansion-panel__content-inner">{children}</div>
      </div>
    </div>
  );
};

export default LegacyExpansionPanel;

import React, { useState } from 'react';
import clsx from 'clsx';

import { Button } from '@shared/ui';

import './demo.styles.scss';

type DemoStep = {
  id: number;
  title: string;
  description: string;
  preview: React.ReactNode;
};

const DEMO_STEPS: DemoStep[] = [
  {
    id: 1,
    title: 'Choose what to sell',
    description: 'Pick between courses, memberships, or consultation sessions.',
    preview: (
      <div className="demo-preview__types">
        <div className="demo-pill">🎓 Course</div>
        <div className="demo-pill">🪐 Membership</div>
        <div className="demo-pill">🎧 Consultation</div>
      </div>
    ),
  },
  {
    id: 2,
    title: 'Build your product',
    description:
      'Structure your content, upload materials, and configure details.',
    preview: (
      <div className="demo-preview__builder">
        <div className="demo-card">Section 1</div>
        <div className="demo-card">Lesson A</div>
        <div className="demo-card">Lesson B</div>
      </div>
    ),
  },
  {
    id: 3,
    title: 'Publish your storefront',
    description:
      'Launch your public page and make your products available instantly.',
    preview: (
      <div className="demo-preview__storefront">
        <div className="demo-card large">Your Storefront</div>
      </div>
    ),
  },
  {
    id: 4,
    title: 'Track your growth',
    description:
      'Monitor sales, engagement, and performance from your dashboard.',
    preview: (
      <div className="demo-preview__analytics">
        <div className="demo-bar" />
        <div className="demo-bar" />
        <div className="demo-bar" />
      </div>
    ),
  },
];

const Demo: React.FC = () => {
  const [activeStep, setActiveStep] = useState(1);

  const step = DEMO_STEPS.find((s) => s.id === activeStep)!;

  return (
    <main className="demo-page">
      {/* HERO */}
      <section className="demo-hero">
        <h1>See Galactica in action</h1>
        <p>
          Walk through how creators build, publish, and sell their products.
        </p>

        <Button variant="primary" onClick={() => setActiveStep(1)}>
          Start demo
        </Button>
      </section>

      {/* WALKTHROUGH */}
      <section className="demo-walkthrough">
        <div className="demo-steps">
          {DEMO_STEPS.map((s) => (
            <div
              key={s.id}
              className={clsx('demo-step', {
                active: s.id === activeStep,
              })}
              onClick={() => setActiveStep(s.id)}
            >
              <span className="step-index">{s.id}</span>
              <div>
                <h3>{s.title}</h3>
                <p>{s.description}</p>
              </div>
            </div>
          ))}
        </div>

        <div className="demo-preview">
          <div key={activeStep} className="demo-preview-inner">
            {step.preview}
          </div>
        </div>
      </section>

      {/* PRODUCT TYPES */}
      <section className="demo-products">
        <h2>Explore what you can build</h2>

        <div className="demo-product-grid">
          <div className="demo-product-card">
            <h3>Courses</h3>
            <p>Structured learning experiences with lessons and sections.</p>
          </div>

          <div className="demo-product-card">
            <h3>Memberships</h3>
            <p>Recurring revenue with exclusive content feeds.</p>
          </div>

          <div className="demo-product-card">
            <h3>Consultations</h3>
            <p>1:1 sessions, coaching, and calls with your audience.</p>
          </div>
        </div>
      </section>

      {/* LEARN */}
      <section className="demo-learn">
        <h2>What you’ll learn</h2>
        <ul>
          <li>How to create and structure products</li>
          <li>How publishing works</li>
          <li>How customers access your content</li>
          <li>How to track performance</li>
        </ul>
      </section>

      {/* CTA */}
      <section className="demo-cta">
        <h2>Ready to launch your creator universe?</h2>

        <Button variant="primary">Get Started</Button>
      </section>
    </main>
  );
};

export default Demo;

import React, {
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import gsap from 'gsap';

import { Button } from '@shared/ui';
import { SectionHeader } from '@domains/marketing/shared';

import './pricing.styles.scss';

type PlanId = 'monthly' | 'bi-yearly' | 'yearly';

interface PricingPlan {
  id: PlanId;
  label: string;
  duration: string;
  price: string;
  description: string;
  badge?: string;
}

const PLANS: PricingPlan[] = [
  {
    id: 'monthly',
    label: 'Monthly',
    duration: '1 month',
    price: '$99',
    description: 'Pay monthly, no commitment. Perfect for trying the platform.',
  },
  {
    id: 'bi-yearly',
    label: 'Bi-yearly',
    duration: '6 months',
    price: '$499',
    description: 'Save 10% with a 6 month commitment and build momentum.',
    badge: 'Save 10%',
  },
  {
    id: 'yearly',
    label: 'Yearly',
    duration: '1 year',
    price: '$999',
    description: 'Best value. Save 20% with a yearly subscription.',
    badge: 'Best value',
  },
];

const getRelativePosition = (index: number, activeIndex: number) => {
  const diff = (index - activeIndex + PLANS.length) % PLANS.length;

  if (diff === 0) {
    return 'center';
  }
  if (diff === 1) {
    return 'right';
  }
  return 'left';
};

const POSITION_MAP = {
  left: {
    x: -340,
    y: 42,
    scale: 0.72,
    opacity: 0.48,
    zIndex: 1,
    rotation: -10,
  },
  center: {
    x: 0,
    y: 0,
    scale: 1,
    opacity: 1,
    zIndex: 3,
    rotation: 0,
  },
  right: {
    x: 340,
    y: 42,
    scale: 0.72,
    opacity: 0.48,
    zIndex: 1,
    rotation: 10,
  },
};

export const Pricing: React.FC = () => {
  const [activeIndex, setActiveIndex] = useState(1);
  const [displayedIndex, setDisplayedIndex] = useState(1);

  const rootRef = useRef<HTMLDivElement | null>(null);
  const planetRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const detailsRef = useRef<HTMLDivElement | null>(null);
  const orbitRef = useRef<HTMLDivElement | null>(null);

  const activePlan = PLANS[displayedIndex];

  const setPlanetRef =
    (index: number) => (element: HTMLButtonElement | null) => {
      planetRefs.current[index] = element;
    };

  const goToPlan = (index: number) => {
    if (index === activeIndex) {
      return;
    }
    setActiveIndex(index);
  };

  const goPrev = () => {
    setActiveIndex((current) => (current - 1 + PLANS.length) % PLANS.length);
  };

  const goNext = () => {
    setActiveIndex((current) => (current + 1) % PLANS.length);
  };

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      planetRefs.current.forEach((planet, index) => {
        if (!planet) {
          return;
        }

        const positionKey = getRelativePosition(index, activeIndex);
        const position = POSITION_MAP[positionKey];

        gsap.set(planet, {
          x: position.x,
          y: position.y,
          scale: position.scale,
          opacity: position.opacity,
          zIndex: position.zIndex,
          rotate: position.rotation,
        });
      });

      gsap.from('.orbit-pricing__title', {
        y: 24,
        opacity: 0,
        duration: 0.7,
        ease: 'power3.out',
      });

      gsap.from('.orbit-pricing__subtitle', {
        y: 18,
        opacity: 0,
        duration: 0.7,
        delay: 0.1,
        ease: 'power3.out',
      });

      gsap.from('.orbit-pricing__stage', {
        scale: 0.94,
        opacity: 0,
        duration: 0.8,
        delay: 0.18,
        ease: 'power3.out',
      });
    }, rootRef);

    return () => ctx.revert();
  }, []);

  useEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({
        defaults: {
          duration: 0.65,
          ease: 'power3.inOut',
        },
      });

      tl.to(detailsRef.current, {
        y: 12,
        opacity: 0,
        duration: 0.22,
        ease: 'power2.out',
        onComplete: () => {
          setDisplayedIndex(activeIndex);
        },
      });

      planetRefs.current.forEach((planet, index) => {
        if (!planet) {
          return;
        }

        const positionKey = getRelativePosition(index, activeIndex);
        const position = POSITION_MAP[positionKey];

        tl.to(
          planet,
          {
            x: position.x,
            y: position.y,
            scale: position.scale,
            opacity: position.opacity,
            rotate: position.rotation,
            zIndex: position.zIndex,
          },
          0,
        );
      });

      tl.to(
        orbitRef.current,
        {
          rotate: '+=18',
          duration: 0.75,
        },
        0,
      );

      tl.to(detailsRef.current, {
        y: 0,
        opacity: 1,
        duration: 0.35,
        ease: 'power3.out',
      });
    }, rootRef);

    return () => ctx.revert();
  }, [activeIndex]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'ArrowLeft') {
        goPrev();
      }
      if (event.key === 'ArrowRight') {
        goNext();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  const planets = useMemo(
    () =>
      PLANS.map((plan, index) => {
        const position = getRelativePosition(index, activeIndex);
        const isActive = position === 'center';

        return (
          <button
            key={plan.id}
            ref={setPlanetRef(index)}
            type="button"
            className={`orbit-pricing__planet orbit-pricing__planet--${plan.id} ${
              isActive ? 'orbit-pricing__planet--active' : ''
            }`}
            onClick={() => goToPlan(index)}
            aria-label={`Select ${plan.label} plan`}
          >
            {plan.badge && (
              <span className="orbit-pricing__badge">{plan.badge}</span>
            )}

            <span className="orbit-pricing__planet-price">{plan.price}</span>
            <span className="orbit-pricing__planet-duration">
              {plan.duration}
            </span>
          </button>
        );
      }),
    [activeIndex],
  );

  return (
    <section className="orbit-pricing" ref={rootRef}>
      <SectionHeader
        title={
          <span>
            Choose Your <span className="primary-word">Orbit</span>
          </span>
        }
        subtitle="Pick the subscription path that fits your launch plan."
      />

      <div className="orbit-pricing__stage">
        <div className="orbit-pricing__orbit" ref={orbitRef} />

        <button
          type="button"
          className="orbit-pricing__nav orbit-pricing__nav--left"
          onClick={goPrev}
          aria-label="Previous plan"
        >
          ‹
        </button>

        <div className="orbit-pricing__planets">{planets}</div>

        <button
          type="button"
          className="orbit-pricing__nav orbit-pricing__nav--right"
          onClick={goNext}
          aria-label="Next plan"
        >
          ›
        </button>
      </div>

      <div className="orbit-pricing__details" ref={detailsRef}>
        <span className="orbit-pricing__details-kicker">
          {activePlan.label}
        </span>
        <h2>{activePlan.duration}</h2>
        <p>{activePlan.description}</p>

        <div className="orbit-pricing__details-footer">
          <strong>{activePlan.price}</strong>
          <Button type="button" variant="primary">
            Get Started
          </Button>
        </div>
      </div>
    </section>
  );
};

export default Pricing;
